package blueprint

import (
	"testing"

	"github.com/AlanD20/groundplane/internal/core"
)

// These fingerprints were generated by the pre-Entry Controller. An unused
// optional credential source must not make an acknowledged Component diverge
// or alter a retained disabled configuration during an in-place upgrade.
func TestLegacyComponentFingerprintsRemainStable(t *testing.T) {
	spec := core.ComponentSpec{Implementation: core.ComponentKindEdgeCloudflare, Enabled: true,
		Settings: core.ComponentCapabilitySettings{ZoneIDs: []string{"net_01ARZ3NDEKTSV4RRFFQ69G5FAV"},
			SecretID: "sec_01ARZ3NDEKTSV4RRFFQ69G5FAV"}}
	got, err := authoredUnitFingerprint("compat-component", spec)
	if err != nil || got != "0c4149775c4b0e4c242f6016d1f7b3294d0041678861f61a44ec61db6c0ba1c0" {
		t.Fatalf("legacy Component identity changed: %s / %v", got, err)
	}
	disabled := core.ComponentConfig{CloudflareTunnel: &core.CloudflareTunnelComponentConfig{
		ZoneIDs: []string{"net_01ARZ3NDEKTSV4RRFFQ69G5FAV"}}}
	got, err = authoredUnitFingerprint("compat-disabled-config", disabled)
	if err != nil || got != "5c95b514dc6ec5fdb9e8357839fbe9df6bac326e70b4486374f38ad01bf12d5f" {
		t.Fatalf("retained disabled configuration changed: %s / %v", got, err)
	}
}
